import csv
import io
import re

INT = re.compile(r"-?\d+")

def convert(value: str):
    if value == "":
        return None
    if INT.fullmatch(value):
        return int(value)
    if value.lower() in ("true", "false"):
        return value.lower() == "true"
    return value

def parse_csv(text: str) -> list[dict]:
    reader = csv.reader(io.StringIO(text))
    header = next(reader, None)
    if header is None:
        return []
    return [{h: convert(v) for h, v in zip(header, row)} for row in reader if any(cell != "" for cell in row)]

