def expand_field(field: str, low: int, high: int) -> list[int]:
    values: set[int] = set()
    for part in field.split(","):
        rng, has_step, step_text = part.partition("/")
        step = int(step_text) if has_step else 1
        if step <= 0:
            raise ValueError(f"bad step in {part!r}")
        if rng == "*":
            start, end = low, high
        elif "-" in rng:
            a, b = rng.split("-", 1)
            start, end = int(a), int(b)
        else:
            start = end = int(rng)
            if has_step:
                end = high
        if start < low or end > high or start > end:
            raise ValueError(f"{part!r} is out of range {low}-{high}")
        values.update(range(start, end + 1, step))
    return sorted(values)

