class FakeClient:
    """Serves pre-defined pages. Records every call so the harness can check you don't over-fetch."""
    def __init__(self, pages):
        self._pages = pages
        self.calls = []

    def list_items(self, page_token=None):
        self.calls.append(page_token)
        index = 0 if page_token is None else int(page_token.removeprefix("p"))
        if index >= len(self._pages):
            raise ValueError(f"invalid page token {page_token!r}")
        nxt = f"p{index + 1}" if index + 1 < len(self._pages) else None
        return {"items": list(self._pages[index]), "next_page_token": nxt}

def __harness__(fn, pages):
    client = FakeClient(pages)
    return {"items": fn(client), "calls": len(client.calls)}

