import functools

def retry(times: int, exceptions: tuple):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            last: BaseException | None = None
            for _ in range(times):
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    last = exc
            assert last is not None
            raise last
        return wrapper
    return decorator

