def token_bucket(capacity: int, rate: float, timestamps: list[float]) -> list[bool]:
    tokens = float(capacity)
    last = timestamps[0] if timestamps else 0.0
    out = []
    for now in timestamps:
        tokens = min(capacity, tokens + (now - last) * rate)
        last = now
        if tokens >= 1 - 1e-9:
            tokens -= 1
            out.append(True)
        else:
            out.append(False)
    return out

