def merge_windows(windows: list[list[int]]) -> dict:
    merged: list[list[int]] = []
    for start, end in sorted(windows):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return {"windows": merged, "minutes": sum(e - s for s, e in merged)}

import heapq
from collections import defaultdict

def deploy_order(deps: dict[str, list[str]]):
    services = set(deps) | {d for ds in deps.values() for d in ds}
    indegree = {s: 0 for s in services}
    dependents: dict[str, list[str]] = defaultdict(list)
    for service, needs in deps.items():
        for need in set(needs):
            indegree[service] += 1
            dependents[need].append(service)
    ready = [s for s, n in indegree.items() if n == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        s = heapq.heappop(ready)
        order.append(s)
        for t in dependents[s]:
            indegree[t] -= 1
            if indegree[t] == 0:
                heapq.heappush(ready, t)
    return order if len(order) == len(services) else None

