def unhealthy_pods(pods: list[dict], max_restarts: int) -> list[dict]:
    report = []
    for pod in pods:
        meta, status = pod.get("metadata", {}), pod.get("status", {})
        phase = status.get("phase", "Unknown")
        statuses = status.get("containerStatuses") or []
        reasons = []
