import re

REF = re.compile(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}")

class Cycle(Exception):
    pass

def resolve(variables: dict[str, str]):
    done: dict[str, str] = {}
    visiting: set[str] = set()

    def value(name: str) -> str:
        if name in done:
            return done[name]
        if name in visiting:
            raise Cycle(name)
        visiting.add(name)
        text = REF.sub(lambda m: value(m.group(1)) if m.group(1) in variables else "", variables[name])
        visiting.discard(name)
        done[name] = text
        return text

    try:
        return {name: value(name) for name in variables}
    except Cycle:
        return None

