import json

def clean_jsonl(text: str) -> dict:
    records, seen = [], set()
    invalid = duplicates = 0
    for line in text.splitlines():
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            invalid += 1
            continue
        email = obj.get("email") if isinstance(obj, dict) else None
        amount = obj.get("amount") if isinstance(obj, dict) else None
        if not isinstance(email, str) or not email.strip() or isinstance(amount, bool) or not isinstance(amount, (int, float)):
            invalid += 1
            continue
        email = email.strip().lower()
        if email in seen:
            duplicates += 1
            continue
        seen.add(email)
        records.append({"email": email, "amount": round(amount, 2)})
    return {"records": records, "invalid": invalid, "duplicates": duplicates}

