        if start + size >= len(tokens):
            return chunks
        start += step

import math
import re
from collections import Counter

def tokens(text: str) -> list[str]:
    return [t for t in re.split(r"[^a-z0-9]+", text.lower()) if t]

def top_k(docs: dict[str, str], query: str, k: int) -> list[str]:
    counts = {doc_id: Counter(tokens(text)) for doc_id, text in docs.items()}
    lengths = {doc_id: sum(c.values()) for doc_id, c in counts.items()}
    df = Counter(t for c in counts.values() for t in c)
    n = len(docs)
    terms = set(tokens(query))
    scored = []
    for doc_id, c in counts.items():
        if not lengths[doc_id]:
            continue
        score = sum(c[t] / lengths[doc_id] * (math.log(n / df[t]) + 1) for t in terms if df[t])
        if score > 0:
            scored.append((-score, doc_id))
    return [doc_id for _, doc_id in sorted(scored)[:k]]

