def alert_periods(counts, window, threshold, min_requests):
    if not counts:
        return []
    data = {m: (r, e) for m, r, e in counts}
    first, last = counts[0][0], counts[-1][0]
    req = err = 0
    periods, open_at = [], None
    for m in range(first, last + 1):
        r, e = data.get(m, (0, 0))
        req, err = req + r, err + e
        old = data.get(m - window)
        if old:
            req, err = req - old[0], err - old[1]
        firing = req >= min_requests and req > 0 and err / req >= threshold
        if firing and open_at is None:
            open_at = m
        elif not firing and open_at is not None:
            periods.append([open_at, m])
            open_at = None
    if open_at is not None:
        periods.append([open_at, None])
    return periods

