def autocomplete(words: list[list], queries: list[str], k: int) -> list[list[str]]:
    best: dict[str, int] = {}
    for word, score in words:
        w = word.lower()
        best[w] = max(score, best.get(w, score))
    root = Node()
    for word, score in best.items():
        node = root
        for ch in word:
            node = node.children.setdefault(ch, Node())
            node.top = sorted(node.top + [(-score, word)])[:k]
    results = []
    for q in queries:
        node = root
        for ch in q.lower():
            node = node.children.get(ch)
            if node is None:
