import heapq
from collections import defaultdict

def fastest_path(links, source, target):
    graph: dict[str, list[tuple[str, int]]] = defaultdict(list)
    for a, b, ms in links:
        graph[a].append((b, ms))
    heap: list[tuple[int, list[str]]] = [(0, [source])]
    done: set[str] = set()
    while heap:
        dist, path = heapq.heappop(heap)
        node = path[-1]
        if node == target:
            return {"ms": dist, "path": path}
        if node in done:
            continue
        done.add(node)
        for nxt, ms in graph[node]:
            if nxt not in done:
                heapq.heappush(heap, (dist + ms, path + [nxt]))
    return None

