def type_ok(value, kind: str) -> bool:
    if kind == "string":
        return isinstance(value, str)
    if kind == "boolean":
        return isinstance(value, bool)
    if kind == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if kind == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if kind == "array":
        return isinstance(value, list)
    if kind == "object":
        return isinstance(value, dict)
    raise ValueError(f"unknown type {kind}")

def check(value, schema: dict, path: str) -> list[str]:
    kind = schema["type"]
    if not type_ok(value, kind):
        return [f"{path}: expected {kind}"]
    errors: list[str] = []
    if kind == "array" and "items" in schema:
        for i, item in enumerate(value):
            errors += check(item, schema["items"], f"{path}[{i}]")
    if kind == "object":
        props = schema.get("properties", {})
        for name in schema.get("required", []):
            if name not in value:
                errors.append(f"{path}.{name}: required")
        for name, sub in props.items():
            if name in value:
                errors += check(value[name], sub, f"{path}.{name}")
    return errors

def validate(data, schema: dict) -> list[str]:
    return sorted(check(data, schema, "$"))

