import json
import re

FENCE = re.compile(r"```(?:json)?\s*\n?(.*?)```", re.DOTALL)

def balanced_object(s: str):
    start = s.find("{")
    if start < 0:
        return None
    depth, in_str, esc = 0, False, False
    for i in range(start, len(s)):
        ch = s[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return s[start : i + 1]
    return None

def strip_trailing_commas(s: str) -> str:
    out: list[str] = []
    in_str = esc = False
    for ch in s:
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in "}]":
            j = len(out) - 1
            while j >= 0 and out[j].isspace():
                j -= 1
            if j >= 0 and out[j] == ",":
                del out[j]
        out.append(ch)
    return "".join(out)

def extract_json(text: str):
    fence = FENCE.search(text)
    candidate = balanced_object(fence.group(1) if fence else text)
    if candidate is None:
        return None
    try:
        value = json.loads(strip_trailing_commas(candidate))
    except ValueError:
        return None
    return value if isinstance(value, dict) else None

