from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")

def cents(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)

@dataclass(frozen=True)
class Line:
    sku: str
    qty: int
    unit_price: Decimal

    @property
    def total(self) -> Decimal:
        return cents(self.unit_price * self.qty)

def build_invoice(lines: list[dict], discount_pct: str, tax_pct: str) -> dict:
    items = [Line(l["sku"], int(l["qty"]), Decimal(l["unit_price"])) for l in lines]
    subtotal = sum((i.total for i in items), Decimal("0"))
    discount = cents(subtotal * Decimal(discount_pct) / 100)
    tax = cents((subtotal - discount) * Decimal(tax_pct) / 100)
    total = subtotal - discount + tax
    return {"lines": [str(i.total) for i in items], "subtotal": str(cents(subtotal)), "discount": str(discount), "tax": str(tax), "total": str(cents(total))}

