from concurrent.futures import ThreadPoolExecutor, as_completed

def check_all(hosts: list[str], workers: int) -> dict:
    results: dict = {}
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {pool.submit(check, host): host for host in hosts}
        for future in as_completed(futures):
            host = futures[future]
            try:
                results[host] = {"ok": True, "ms": future.result()}
            except Exception as exc:
                results[host] = {"ok": False, "error": type(exc).__name__}
    return results

def error_rate(m: dict) -> float:
    return m["errors"] / m["requests"] if m["requests"] else 0.0

def canary_decision(baseline, canary, min_requests, max_error_delta, max_latency_ratio):
    if canary["requests"] < min_requests:
        return {"decision": "wait", "reasons": ["insufficient-traffic"]}
    reasons = []
    if error_rate(canary) > error_rate(baseline) + max_error_delta:
        reasons.append("error-rate")
    if canary["p95_ms"] > baseline["p95_ms"] * (1 + max_latency_ratio):
        reasons.append("latency")
    return {"decision": "rollback" if reasons else "promote", "reasons": reasons}

