import hashlib
from bisect import bisect_left
from collections import Counter

def h(s: str) -> int:
    return int(hashlib.md5(s.encode()).hexdigest()[:8], 16)

def build(nodes, vnodes):
    ring = sorted((h(f"{n}#{i}"), n) for n in nodes for i in range(vnodes))
    return [p for p, _ in ring], ring

def owner(points, ring, key: str) -> str:
    return ring[bisect_left(points, h(key)) % len(ring)][1]

def hash_ring(nodes, vnodes, keys, remove):
    points, ring = build(nodes, vnodes)
    before = {k: owner(points, ring, k) for k in keys}
    points2, ring2 = build([n for n in nodes if n != remove], vnodes)
    moved = sum(1 for k in keys if owner(points2, ring2, k) != before[k])
    return {"assignment": before, "counts": dict(Counter(before.values())), "moved": moved}

