def rollout(replicas: int, max_surge: int, max_unavailable: int):
    if max_surge == 0 and max_unavailable == 0:
        return None
    old, ready, starting = replicas, 0, 0
    steps = []
    while not (ready == replicas and old == 0):
        ready += starting
        starting = 0
        old -= max(0, min(old, old + ready - (replicas - max_unavailable)))
        starting = max(0, min(replicas + max_surge - (old + ready), replicas - ready))
        steps.append([old, ready, starting])
        if len(steps) > 10 * replicas + 10:
            raise RuntimeError("rollout does not converge")
    return {"steps": steps, "count": len(steps)}

def parse(v: str) -> tuple[int, ...]:
    return tuple(int(x) for x in v.split("."))

def satisfies(version: str, constraint: str) -> bool:
    v = parse(version)
    for clause in constraint.split(","):
        clause = clause.strip()
        if clause in ("", "*"):
            continue
        for op in (">=", "<", "==", "^"):
            if clause.startswith(op):
                target = parse(clause[len(op):])
                break
        else:
            raise ValueError(f"bad constraint {clause!r}")
        if op == ">=" and not v >= target:
            return False
        if op == "<" and not v < target:
            return False
        if op == "==" and v != target:
            return False
        if op == "^" and not (v[0] == target[0] and v >= target):
            return False
    return True

def resolve_versions(available, requires, deps):
    def search(chosen: dict, constraints: dict):
        pending = sorted(p for p in constraints if p not in chosen)
        if not pending:
            return chosen
        pkg = pending[0]
        for version in sorted(available.get(pkg, []), key=parse, reverse=True):
            if not all(satisfies(version, c) for c in constraints[pkg]):
                continue
            merged = {p: list(cs) for p, cs in constraints.items()}
            for dep, c in deps.get(f"{pkg}=={version}", {}).items():
                merged.setdefault(dep, []).append(c)
            if all(all(satisfies(chosen[p], c) for c in merged[p]) for p in chosen):
                found = search({**chosen, pkg: version}, merged)
                if found:
                    return found
        return None

    return search({}, {p: [c] for p, c in requires.items()})

import math

def cos(a, b) -> float:
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    return 0.0 if na == 0 or nb == 0 else sum(x * y for x, y in zip(a, b)) / (na * nb)

def mmr(query, docs, k, lam):
    rel = {d: cos(query, v) for d, v in docs.items()}
    selected: list[str] = []
    remaining = set(docs)
    while remaining and len(selected) < k:
        def score(d: str) -> float:
            redundancy = max((cos(docs[d], docs[s]) for s in selected), default=0.0)
            return lam * rel[d] - (1 - lam) * redundancy
        best = min(remaining, key=lambda d: (-round(score(d), 12), d))
        selected.append(best)
        remaining.remove(best)
    return selected

def cost(message: dict) -> int:
    return len(message["content"].split()) + 4

def fit_messages(messages: list[dict], budget: int):
    n_system = 0
    while n_system < len(messages) and messages[n_system]["role"] == "system":
        n_system += 1
    system, rest = messages[:n_system], messages[n_system:]
    system_cost = sum(cost(m) for m in system)
    if system_cost + sum(cost(m) for m in rest) <= budget:
        return list(messages)
    left = budget - system_cost - 8
    if left < 0:
        return None
    kept: list[dict] = []
    for message in reversed(rest):
        if cost(message) > left:
            break
        kept.append(message)
        left -= cost(message)
    kept.reverse()
    note = {"role": "system", "content": f"[{len(rest) - len(kept)} earlier messages omitted]"}
    return system + [note] + kept

