from collections import Counter

def ratio(a: float, b: float) -> float:
    return a / b if b else 0.0

def report(y_true, y_pred):
    tp, fp, fn = Counter(), Counter(), Counter()
    for t, p in zip(y_true, y_pred):
        if t == p:
            tp[t] += 1
        else:
            fp[p] += 1
            fn[t] += 1
    labels = {}
    for label in sorted(set(y_true) | set(y_pred)):
        precision = ratio(tp[label], tp[label] + fp[label])
        recall = ratio(tp[label], tp[label] + fn[label])
        f1 = ratio(2 * precision * recall, precision + recall)
        labels[label] = {"precision": round(precision, 4), "recall": round(recall, 4), "f1": round(f1, 4), "support": tp[label] + fn[label]}
    n = len(labels)
    macro = {m: round(ratio(sum(v[m] for v in labels.values()), n), 4) for m in ("precision", "recall", "f1")}
    accuracy = round(ratio(sum(tp.values()), len(y_true)), 4)
    return {"labels": labels, "macro": macro, "accuracy": accuracy}

