import re

SEVERITY = {"critical": 0, "high": 1, "medium": 2, "low": 3}

def normalize(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()

def compare(a: str, b: str) -> int:
    x = [int(p) for p in a.split(".")]
    y = [int(p) for p in b.split(".")]
    n = max(len(x), len(y))
    x += [0] * (n - len(x))
    y += [0] * (n - len(y))
    return (x > y) - (x < y)

def matches(version: str, affected: str) -> bool:
    for clause in affected.split(","):
        clause = clause.strip()
        for op in (">=", "<=", "==", ">", "<"):
            if clause.startswith(op):
                c = compare(version, clause[len(op):].strip())
                ok = {">=": c >= 0, "<=": c <= 0, "==": c == 0, ">": c > 0, "<": c < 0}[op]
                if not ok:
                    return False
                break
        else:
            raise ValueError(f"bad clause {clause!r}")
    return True

def audit(lock: dict, advisories: list[dict]) -> list[dict]:
    installed = {normalize(name): version for name, version in lock.items()}
    findings = []
    for adv in advisories:
        name = normalize(adv["package"])
        version = installed.get(name)
        if version is not None and matches(version, adv["affected"]):
            findings.append({"package": name, "version": version, "advisory": adv["id"], "severity": adv["severity"], "fixed": adv["fixed"]})
    return sorted(findings, key=lambda f: (SEVERITY[f["severity"]], f["package"], f["advisory"]))

import math
import re
from collections import Counter

PATTERNS = [
    ("aws-access-key", re.compile(r"\bAKIA[0-9A-Z]{16}\b")),
    ("github-token", re.compile(r"\bghp_[A-Za-z0-9]{36}\b")),
    ("private-key", re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----")),
]
GENERIC = re.compile(r"""(?i)\b[\w.-]*(?:secret|token|password|api_key)[\w.-]*\s*[:=]\s*["']?([^\s"']+)""")

def entropy(value: str) -> float:
    counts = Counter(value)
    n = len(value)
    return -sum(c / n * math.log2(c / n) for c in counts.values())

def scan(text: str) -> list[dict]:
    findings = set()
    for n, line in enumerate(text.splitlines(), start=1):
        if "nosecret" in line:
            continue
        for kind, pattern in PATTERNS:
            if pattern.search(line):
                findings.add((n, kind))
        for m in GENERIC.finditer(line):
            value = m.group(1)
            if len(value) >= 12 and entropy(value) >= 3.5:
                findings.add((n, "generic-secret"))
    return [{"line": n, "kind": k} for n, k in sorted(findings)]

