def sync(client, sleep) -> list:
    items: list = []
    cursor = None
    failures = 0
    while True:
        response = client.get(cursor)
        status = response["status"]
        if status == 200:
            items.extend(response["items"])
            failures = 0
            cursor = response.get("next")
            if cursor is None:
                return items
        elif status == 429:
            sleep(response["retry_after"])
        elif status == 503:
            failures += 1
            if failures >= 5:
                raise RuntimeError(f"giving up on cursor {cursor!r} after {failures} attempts")
            sleep(min(8, 2 ** (failures - 1)))
        else:
            raise RuntimeError(f"unexpected status {status}")

solution.explanation:
429 is the server telling you exactly when to come back, so it shouldn't consume your failure budget;
503 is an unknown outage, so back off exponentially and give up eventually. Retrying the same cursor
keeps the sync exactly-once per page.

