from datetime import date, datetime, timedelta

def expand(field: str, low: int, high: int) -> set[int]:
    values: set[int] = set()
    for part in field.split(","):
        rng, _, step = part.partition("/")
        step_n = int(step) if step else 1
        if rng == "*":
            a, b = low, high
        elif "-" in rng:
            a, b = (int(x) for x in rng.split("-", 1))
        else:
            a = b = int(rng)
            if step:
                b = high
        values.update(range(a, b + 1, step_n))
    return values

def next_run(expr: str, start: str):
    minute_f, hour_f, dom_f, month_f, dow_f = expr.split()
    minutes, hours = sorted(expand(minute_f, 0, 59)), sorted(expand(hour_f, 0, 23))
    doms, months = expand(dom_f, 1, 31), expand(month_f, 1, 12)
    dows = {d % 7 for d in expand(dow_f, 0, 7)}
    t0 = datetime.fromisoformat(start)
    day = t0.date()
    for _ in range(366 * 5 + 2):
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = (day.weekday() + 1) % 7 in dows
            if dom_f != "*" and dow_f != "*":
                day_ok = dom_ok or dow_ok
            else:
                day_ok = dom_ok and dow_ok
            if day_ok:
                for h in hours:
                    for m in minutes:
                        t = datetime(day.year, day.month, day.day, h, m)
                        if t > t0:
                            return t.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    return None

