def plan_capacity(demand, max_servers, initial, run_cost, change_cost):
    if any(d > max_servers for d in demand):
        return None
    T = len(demand)
    if T == 0:
        return {"cost": 0, "plan": []}
    INF = float("inf")
    best = [[INF] * (max_servers + 1) for _ in range(T)]
    for s in range(demand[-1], max_servers + 1):
        best[-1][s] = run_cost * s
    for t in range(T - 2, -1, -1):
        for s in range(demand[t], max_servers + 1):
            best[t][s] = run_cost * s + min(change_cost * abs(s2 - s) + best[t + 1][s2] for s2 in range(demand[t + 1], max_servers + 1))
    plan, prev, total = [], initial, None
    for t in range(T):
        options = [(change_cost * abs(s - prev) + best[t][s], s) for s in range(demand[t], max_servers + 1)]
        cost_here = min(c for c, _ in options)
        if total is None:
            total = cost_here
        s = min(s for c, s in options if c == cost_here)
        plan.append(s)
        prev = s
    return {"cost": int(total), "plan": plan}

