def parse_sse(chunks: list[str]) -> list[dict]:
    events: list[dict] = []
    buffer = ""
    event_type, data, last_id = "", [], None
    for chunk in chunks:
        buffer += chunk
        while "\n" in buffer:
            line, buffer = buffer.split("\n", 1)
            if line.endswith("\r"):
                line = line[:-1]
            if line == "":
                if data:
                    events.append({"event": event_type or "message", "data": "\n".join(data), "id": last_id})
                event_type, data = "", []
                continue
            if line.startswith(":"):
                continue
            field, _, value = line.partition(":")
            if value.startswith(" "):
                value = value[1:]
            if field == "data":
                data.append(value)
            elif field == "event":
                event_type = value
            elif field == "id":
                last_id = value
    return events

