        self.max_retries = max_retries
        self.threshold = breaker_threshold
        self.cooldown = cooldown
        self.failures: dict[str, int] = {p.name: 0 for p in providers}
        self.opened_at: dict[str, float] = {}

    def _is_open(self, name: str) -> bool:
        opened = self.opened_at.get(name)
        return opened is not None and self.clock() - opened < self.cooldown

    def _record_failure(self, name: str) -> bool:
        """Count a failure; True if the circuit is now open."""
        self.failures[name] += 1
        if self.failures[name] >= self.threshold:
            self.opened_at[name] = self.clock()
            return True
        return False

    def complete(self, prompt):
        attempts = 0
        for provider in self.providers:
            name = provider.name
            if self._is_open(name):
                continue
            for i in range(self.max_retries + 1):
                attempts += 1
                try:
                    text = provider.complete(prompt)
                except ProviderError as err:
                    opened = self._record_failure(name)
                    if err.status == 400:
                        raise BadRequest(str(err)) from err
                    if opened or err.status not in RETRYABLE or i == self.max_retries:
                        break
                    self.sleep(0.5 * 2**i)
                    continue
                self.failures[name] = 0
                self.opened_at.pop(name, None)
                return {"text": text, "provider": name, "attempts": attempts}
        raise AllProvidersFailed(f"no provider answered after {attempts} attempts")

