class BadReference(Exception):
    pass

def resolve(value, outputs):
    if isinstance(value, str) and value.startswith("$"):
        sid, _, key = value[1:].partition(".")
        if sid not in outputs:
            raise BadReference(value)
        out = outputs[sid]
        if not key:
            return out
        if not isinstance(out, dict) or key not in out:
            raise BadReference(value)
        return out[key]
    if isinstance(value, list):
        return [resolve(v, outputs) for v in value]
    if isinstance(value, dict):
        return {k: resolve(v, outputs) for k, v in value.items()}
    return value

def execute_plan(plan: list[dict], budget: int) -> dict:
    status: dict[str, str] = {}
    outputs: dict = {}
    waves: list[list[str]] = []
    calls = 0

    def run(step) -> None:
        nonlocal calls
        tool = TOOLS.get(step["tool"])
        if tool is None:
            status[step["id"]] = "unknown_tool"
            return
        try:
            args = resolve(step.get("args", {}), outputs)
        except BadReference:
            status[step["id"]] = "bad_reference"
            return
        for attempt in (1, 2):
            if calls >= budget:
                status[step["id"]] = "budget_exhausted"
                return
            calls += 1
            try:
                outputs[step["id"]] = tool(**args)
                status[step["id"]] = "ok"
                return
            except ToolError as err:
                if err.retryable and attempt == 1:
                    continue
                status[step["id"]] = "tool_error"
                return
            except Exception:
                status[step["id"]] = "tool_error"
                return

    while True:
        changed = True
        while changed:
            changed = False
            for step in plan:
                sid = step["id"]
                if sid in status:
                    continue
                if any(d in status and status[d] != "ok" for d in step.get("after", [])):
                    status[sid] = "skipped"
                    changed = True
        wave = [s for s in plan if s["id"] not in status and all(status.get(d) == "ok" for d in s.get("after", []))]
        if not wave:
            break
        waves.append([s["id"] for s in wave])
        for step in wave:
            run(step)
    for step in plan:
        status.setdefault(step["id"], "blocked")
    return {"status": status, "outputs": {k: v for k, v in outputs.items() if status.get(k) == "ok"}, "waves": waves, "calls": calls}

def commit_indexes(log_terms, term, cluster_size, commit, acks):
    matches: dict[str, int] = {}
    out = []
    for follower, match in acks:
        matches[follower] = max(matches.get(follower, 0), min(match, len(log_terms)))
        values = [len(log_terms)] + list(matches.values())
        values += [0] * (cluster_size - len(values))
        values.sort(reverse=True)
        replicated = values[cluster_size // 2]
        for n in range(replicated, commit, -1):
            if log_terms[n - 1] == term:
                commit = n
                break
        out.append(commit)
    return out

