def compare(a: list[int], b: list[int]) -> str:
    le = all(x <= y for x, y in zip(a, b))
    ge = all(x >= y for x, y in zip(a, b))
    if le and ge:
        return "same"
    if le:
        return "before"
    if ge:
        return "after"
    return "concurrent"

def vector_clocks(procs, events, queries):
    index = {p: i for i, p in enumerate(procs)}
    current = {p: [0] * len(procs) for p in procs}
    in_flight: dict[str, list[int]] = {}
    clocks = []
    for e in events:
        clock = list(current[e["proc"]])
        if e["type"] == "recv":
            clock = [max(a, b) for a, b in zip(clock, in_flight[e["msg"]])]
        clock[index[e["proc"]]] += 1
        if e["type"] == "send":
            in_flight[e["msg"]] = list(clock)
        current[e["proc"]] = clock
        clocks.append(clock)
    return {"clocks": clocks, "answers": [compare(clocks[i], clocks[j]) for i, j in queries]}

