import json

TYPES = {
    "string": lambda v: isinstance(v, str),
    "integer": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "boolean": lambda v: isinstance(v, bool),
}

class RpcError(Exception):
    def __init__(self, code: int, message: str):
        super().__init__(message)
        self.code, self.message = code, message

def error(id_, code, message):
    return {"jsonrpc": "2.0", "id": id_, "error": {"code": code, "message": message}}

def valid_id(msg):
    id_ = msg.get("id") if isinstance(msg, dict) else None
    return id_ if isinstance(id_, str) or (isinstance(id_, int) and not isinstance(id_, bool)) else None

def check_arguments(schema: dict, args) -> bool:
    if not isinstance(args, dict):
        return False
    if any(k not in args for k in schema.get("required", [])):
        return False
    for key, prop in schema.get("properties", {}).items():
        if key in args and not TYPES[prop["type"]](args[key]):
            return False
    return True

def dispatch(method: str, params):
    if method == "initialize":
        return {"protocolVersion": "2025-06-18", "capabilities": {"tools": {}}, "serverInfo": {"name": "practice", "version": "1.0.0"}}
    if method == "tools/list":
        return {"tools": [{"name": n, "description": t["description"], "inputSchema": t["inputSchema"]} for n, t in sorted(TOOLS.items())]}
    if method == "tools/call":
        params = params if isinstance(params, dict) else {}
        tool = TOOLS.get(params.get("name"))
        args = params.get("arguments", {})
        if tool is None or not check_arguments(tool["inputSchema"], args):
            raise RpcError(-32602, "Invalid params")
        try:
            text, is_error = str(tool["fn"](**args)), False
        except Exception as exc:
            text, is_error = str(exc), True
        return {"content": [{"type": "text", "text": text}], "isError": is_error}
    raise RpcError(-32601, "Method not found")

def one(msg):
    if not isinstance(msg, dict) or msg.get("jsonrpc") != "2.0" or not isinstance(msg.get("method"), str):
        return error(valid_id(msg), -32600, "Invalid Request")
    notification = "id" not in msg
    try:
        response = {"jsonrpc": "2.0", "id": msg["id"] if not notification else None, "result": dispatch(msg["method"], msg.get("params"))}
    except RpcError as exc:
        response = error(valid_id(msg), exc.code, exc.message)
    return None if notification else response

def handle(raw: str):
    try:
        msg = json.loads(raw)
    except ValueError:
        return json.dumps(error(None, -32700, "Parse error"))
    if isinstance(msg, list):
        if not msg:
            return json.dumps(error(None, -32600, "Invalid Request"))
        responses = [r for r in (one(m) for m in msg) if r is not None]
        return json.dumps(responses) if responses else None
    response = one(msg)
    return None if response is None else json.dumps(response)

