from collections import defaultdict

def process(messages: list[dict]) -> dict:
    expected: dict[str, int] = defaultdict(lambda: 1)
    buffer: dict[str, dict[int, dict]] = defaultdict(dict)
    seen: set[str] = set()
    state: dict[str, float] = {}
    applied: list[str] = []
    duplicates = 0
    for m in messages:
        key, seq = m["key"], m["seq"]
        if m["msg_id"] in seen or seq < expected[key] or seq in buffer[key]:
            duplicates += 1
            continue
        seen.add(m["msg_id"])
        buffer[key][seq] = m
        while expected[key] in buffer[key]:
            msg = buffer[key].pop(expected[key])
            if msg["op"] == "set":
                state[key] = msg["value"]
            else:
                state[key] = state.get(key, 0) + msg["value"]
            applied.append(msg["msg_id"])
            expected[key] += 1
    pending = {k: sorted(b) for k, b in buffer.items() if b}
    return {"state": state, "applied": applied, "duplicates": duplicates, "pending": pending}

